 Để khắc phục vấn đề về DI và cấu hình, chúng ta có thể kết hợp Functional Options Pattern và mở rộng khái niệm Provider.  Cấu trúc:  package main import ( &quot;fmt&quot; &quot;log&quot; &quot;strings&quot; &quot;sync&quot; &quot;time&quot; ) // Logger là một dependency mẫu type Logger interface { Infof(format string, args ...interface{}) Errorf(format string, args ...interface{}) } type defaultLogger struct{} func (d *defaultLogger) Infof(format string, args ...interface{}) { log.Printf(&quot;INFO: &quot;+format, args...) } func (d *defaultLogger) Errorf(format string, args ...interface{}) { log.Printf(&quot;ERROR: &quot;+format, args...) } // Command interface vẫn giữ nguyên type Command interface { Name() string Description() string Execute(ctx Context, args []string) error // Context now includes dependencies } // ApplicationContext chứa các dependencies dùng chung type ApplicationContext struct { Logger Logger // Thêm các dependencies khác như DBClient, Config, v.v. } // Context cho mỗi lệnh thực thi, có thể là con của context.Context chuẩn Go type Context struct { // Có thể chứa context.Context của Go để quản lý cancellation, deadline // goCtx context.Context AppCtx *ApplicationContext } // --- Commands with dependencies --- type GreetCommand struct { Greeting string } func (c *GreetCommand) Name() string { return &quot;greet&quot; } func (c *GreetCommand) Description() string { return &quot;Greets the given name with a custom message&quot; } func (c *GreetCommand) Execute(ctx Context, args []string) error { if len(args) &lt; 1 { ctx.AppCtx.Logger.Errorf(&quot;usage: greet &lt;name&gt;&quot;) return fmt.Errorf(&quot;usage: greet &lt;name&gt;&quot;) } ctx.AppCtx.Logger.Infof(&quot;Executing greet command for %s&quot;, args[0]) fmt.Printf(&quot;%s, %s!
&quot;, c.Greeting, args[0]) return nil } // --- Functional Options for Command Creation --- type CommandOption func(*CommandBuilder) type CommandBuilder struct { command Command } func WithGreeting(msg string) CommandOption { return func(cb *CommandBuilder) { if gc, ok := cb.command.(*GreetCommand); ok { gc.Greeting = msg } } } // NewGreetCommand factory function func NewGreetCommand(opts ...CommandOption) *GreetCommand { cmd := &amp;GreetCommand{Greeting: &quot;Hello&quot;} // Default greeting builder := &amp;CommandBuilder{command: cmd} for _, opt := range opts { opt(builder) } return cmd } // --- Provider Interface --- // CommandProvider là một interface cho các đối tượng có thể cung cấp lệnh type CommandProvider interface { GetCommands(appCtx *ApplicationContext) []Command } // BasicProvider implements CommandProvider type BasicProvider struct { commands []Command } func NewBasicProvider() *BasicProvider { return &amp;BasicProvider{} } func (p *BasicProvider) AddCommand(cmd Command) { p.commands = append(p.commands, cmd) } func (p *BasicProvider) GetCommands(appCtx *ApplicationContext) []Command { // In a more complex scenario, providers might dynamically create commands // or perform additional setup using appCtx here. return p.commands } // CommandRegistry cải tiến type CommandRegistry struct { commands map[string]Command appCtx *ApplicationContext mu sync.RWMutex } func NewCommandRegistry(appCtx *ApplicationContext) *CommandRegistry { return &amp;CommandRegistry{ commands: make(map[string]Command), appCtx: appCtx, } } func (r *CommandRegistry) RegisterProvider(provider CommandProvider) { r.mu.Lock() defer r.mu.Unlock() for _, cmd := range provider.GetCommands(r.appCtx) { if _, exists := r.commands[cmd.Name()]; exists { r.appCtx.Logger.Errorf(&quot;Command '%s' from provider already registered. Skipping.&quot;, cmd.Name()) continue } r.commands[cmd.Name()] = cmd r.appCtx.Logger.Infof(&quot;Registered command: %s&quot;, cmd.Name()) } } func (r *CommandRegistry) Get(name string) (Command, bool) { r.mu.RLock() defer r.mu.RUnlock() cmd, ok := r.commands[name] return cmd, ok } func (r *CommandRegistry) List() []Command { r.mu.RLock() defer r.mu.RUnlock() var cmds []Command for _, cmd := range r.commands { cmds = append(cmds, cmd) } return cmds } func main() { appCtx := &amp;ApplicationContext{ Logger: &amp;defaultLogger{}, } registry := NewCommandRegistry(appCtx) // Create a provider and register commands with functional options basicProvider := NewBasicProvider() basicProvider.AddCommand(NewGreetCommand()) // Default greeting basicProvider.AddCommand(NewGreetCommand(WithGreeting(&quot;Hiya&quot;))) // Custom greeting registry.RegisterProvider(basicProvider) // List commands fmt.Println(&quot;
Available commands:&quot;) for _, cmd := range registry.List() { fmt.Printf(&quot; - %s: %s
&quot;, cmd.Name(), cmd.Description()) } // Execute commands fmt.Println(&quot;
Executing commands:&quot;) execCtx := Context{AppCtx: appCtx} // Context for execution if cmd, ok := registry.Get(&quot;greet&quot;); ok { if err := cmd.Execute(execCtx, []string{&quot;Alice&quot;}); err != nil { appCtx.Logger.Errorf(&quot;Error executing greet: %v&quot;, err) } } else { appCtx.Logger.Errorf(&quot;Command 'greet' not found.&quot;) } if cmd, ok := registry.Get(&quot;greet&quot;); ok { // This will still execute the first 'greet' command registered // demonstrating that if you need different instances, you need to register them with different names if err := cmd.Execute(execCtx, []string{&quot;Bob&quot;}); err != nil { appCtx.Logger.Errorf(&quot;Error executing greet: %v&quot;, err) } } // For commands needing different config, they would have different names or be instantiated differently // For instance: // basicProvider.AddCommand(NewGreetCommand(WithGreeting(&quot;Hola&quot;), WithName(&quot;hola&quot;))) // If command name can be changed // This shows the limitation if multiple commands share the same Name() but have different configurations. // You might need to make Command.Name() dynamic based on config, or use a &quot;command factory&quot;. }   Ưu điểm:  Dependency Injection: ApplicationContext và Context cho phép truyền các dependencies cần thiết cho các lệnh.Cấu hình linh hoạt: Functional Options Pattern cho phép cấu hình các lệnh một cách rõ ràng và có thể mở rộng.Grouping Commands: CommandProvider cho phép nhóm các lệnh và cung cấp chúng theo từng lô. Điều này rất hữu ích cho các mô-đun hoặc plugin.Lifecycle Management (Cải thiện): GetCommands(appCtx *ApplicationContext) của Provider có thể được dùng để khởi tạo hoặc cấu hình các lệnh dựa trên context ứng dụng.  Nhược điểm:  Phức tạp hơn giải pháp 1.Vẫn có thể gặp vấn đề nếu nhiều lệnh cấu hình khác nhau lại có cùng Name(). Có thể giải quyết bằng cách thay đổi Name() thành một trường được cấu hình, hoặc bằng cách sử dụng Command Factories.
